-- V14: governed policy registry, action proposals and append-only action events.
create table if not exists public.action_policies(
 id uuid primary key default gen_random_uuid(), policy_key text not null, version integer not null check(version>0), name text not null,
 category text not null check(category in ('operations','inventory','service','commercial','customer','system')),
 alert_type text, min_severity text not null default 'warning' check(min_severity in ('info','warning','high','critical')),
 action_kind text not null check(action_kind in ('human_task','notify_admin','record_decision')),
 impact_class text not null check(impact_class in ('advisory','reversible','high_impact')),
 approval_mode text not null default 'single' check(approval_mode in ('none','single','dual')),
 expires_after_hours integer not null default 48 check(expires_after_hours between 1 and 720), enabled boolean not null default true,
 action_template jsonb not null default '{}'::jsonb, conditions jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(policy_key,version),
 check(not(impact_class='high_impact' and approval_mode='none'))
);
alter table public.action_policies enable row level security;revoke all on public.action_policies from public,anon,authenticated;grant select,insert,update on public.action_policies to service_role;

create table if not exists public.action_proposals(
 id uuid primary key default gen_random_uuid(), proposal_key text not null unique, alert_id uuid not null references public.control_alerts(id) on delete restrict,
 policy_id uuid not null references public.action_policies(id) on delete restrict, status text not null default 'proposed' check(status in ('proposed','simulated','approved','rejected','expired','executed','cancelled')),
 action_kind text not null check(action_kind in ('human_task','notify_admin','record_decision')), impact_class text not null check(impact_class in ('advisory','reversible','high_impact')),
 risk_score integer not null default 0 check(risk_score between 0 and 100), rationale text not null, proposed_payload jsonb not null default '{}'::jsonb,
 source_snapshot jsonb not null default '{}'::jsonb, simulation_snapshot jsonb, simulation_hash text, simulated_at timestamptz,
 expires_at timestamptz not null, approved_at timestamptz, rejected_at timestamptz, executed_at timestamptz, cancelled_at timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists action_proposals_queue_idx on public.action_proposals(status,risk_score desc,expires_at asc);
create index if not exists action_proposals_alert_idx on public.action_proposals(alert_id,status);
alter table public.action_proposals enable row level security;revoke all on public.action_proposals from public,anon,authenticated;grant select,insert,update on public.action_proposals to service_role;

create table if not exists public.action_proposal_events(
 id bigint generated by default as identity primary key,event_key text not null unique,proposal_id uuid not null references public.action_proposals(id) on delete restrict,
 event_type text not null check(event_type in ('proposed','simulated','approved','rejected','expired','executed','cancelled','approval_added','simulation_invalidated')),
 from_status text,to_status text,actor_id uuid references auth.users(id) on delete set null,metadata jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now()
);
alter table public.action_proposal_events enable row level security;revoke all on public.action_proposal_events from public,anon,authenticated;grant select,insert on public.action_proposal_events to service_role;

create table if not exists public.action_approvals(
 id uuid primary key default gen_random_uuid(),proposal_id uuid not null references public.action_proposals(id) on delete restrict,slot integer not null check(slot in (1,2)),approver_id uuid not null references auth.users(id) on delete restrict,
 decision text not null check(decision in ('approved','rejected')),note text,created_at timestamptz not null default now(),unique(proposal_id,slot),unique(proposal_id,approver_id)
);
alter table public.action_approvals enable row level security;revoke all on public.action_approvals from public,anon,authenticated;grant select,insert on public.action_approvals to service_role;

create table if not exists public.action_executions(
 id uuid primary key default gen_random_uuid(),execution_key text not null unique,proposal_id uuid not null references public.action_proposals(id) on delete restrict,
 adapter text not null check(adapter in ('human_task','notify_admin','record_decision')),status text not null check(status in ('succeeded','failed')),
 input_snapshot jsonb not null default '{}'::jsonb,result jsonb not null default '{}'::jsonb,error_message text,executed_by uuid references auth.users(id) on delete set null,executed_at timestamptz not null default now()
);
alter table public.action_executions enable row level security;revoke all on public.action_executions from public,anon,authenticated;grant select,insert on public.action_executions to service_role;
